using System;
namespace Downfield {
public partial class Simulation {
 void ReleaseBlock(Player p){if(p.BlockPartner>=0&&p.BlockPartner<Players.Count){Player other=Players[p.BlockPartner];if(other.BlockPartner==Players.IndexOf(p))other.BlockPartner=-1;}p.BlockPartner=-1;p.Engagement=0;}
 bool EligibleBlocker(Player p){return p.Active&&p.Team==0&&p!=Controlled&&p.KnockTime<=0&&(p.Role=="OL"||State==Phase.Live&&(Controlled.Role!="QB"||Controlled.Z>Spot)&&p.Z>Controlled.Z-2);}
 void ApproachBlock(Player p,float dt){if(p.Blocked>0||p.KnockTime>0){p.VX=p.VZ=0;return;}if(p.BlockPartner>=0){p.VX=p.VZ=0;p.Pose="block";p.PoseTime=.1f;return;}Player nearest=null;float best=p.Role=="OL"?5.5f:10f;foreach(Player d in Players){if(d.Team!=1||!d.Active||d.BlockPartner>=0||d.KnockTime>0||d.Blocked>0)continue;float distance=Distance(p.X,p.Z,d.X,d.Z);if(p.Role=="OL"&&d.Z<p.Z-1.5f)distance+=2;float score=distance;if(RunPlay&&Playbook>=6){float[] lane=RunPoint(1);score+=Math.Abs(d.X-lane[0])*.08f;}if(score<best){best=score;nearest=d;}}if(nearest==null){if(p.Role!="OL")Move(p,Controlled.X+(p.StartX<0?-3:3),Controlled.Z+5,p.Speed*.85f,dt);else p.VX=p.VZ=0;return;}float targetZ=nearest.Z-.9f;if(p.Role=="OL"&&!RunPlay&&Controlled.Role=="QB")targetZ=Math.Max(Spot-2.8f,targetZ);Move(p,nearest.X,targetZ,p.Role=="OL"?Math.Min(p.Speed,4.5f+Running*.1f):p.Speed*.85f,dt);}
 void ResolveLineContacts(float dt){
  // Each engagement belongs to one blocker and one rusher, and advances once per frame.
  foreach(Player blocker in Players)if(blocker.Team==0&&blocker.BlockPartner>=0){Player rusher=Players[blocker.BlockPartner];if(!EligibleBlocker(blocker)||rusher.KnockTime>0||Distance(blocker.X,blocker.Z,rusher.X,rusher.Z)>2.2f){ReleaseBlock(blocker);continue;}blocker.Engagement+=dt;blocker.Pose=rusher.Pose="block";blocker.PoseTime=rusher.PoseTime=.1f;if(blocker.Engagement>=blocker.BlockLimit){rusher.LastBlocker=Players.IndexOf(blocker);ReleaseBlock(blocker);rusher.ShedTime=.65f;blocker.ShedTime=.45f;blocker.Blocked=.18f;rusher.ShedSide=Controlled.X>=blocker.X?1:-1;}}
  foreach(Player blocker in Players)if(EligibleBlocker(blocker))foreach(Player rusher in Players){if(rusher.Team!=1||!rusher.Active||rusher.KnockTime>0||rusher.Blocked>0)continue;float dx=rusher.X-blocker.X,dz=rusher.Z-blocker.Z,distance=(float)Math.Sqrt(dx*dx+dz*dz);if(distance>1.35f)continue;
   if(blocker.BlockPartner<0&&rusher.BlockPartner<0&&blocker.ShedTime<=0&&rusher.ShedTime<=0&&!(blocker.Role=="OL"&&!RunPlay&&rusher.Z<blocker.Z-.15f)){blocker.BlockPartner=Players.IndexOf(rusher);rusher.BlockPartner=Players.IndexOf(blocker);blocker.Engagement=0;blocker.BlockLimit=Clamp((RunPlay?.68f:blocker.Role=="OL"?.95f:.6f)+(float)random.NextDouble()*.5f+(blocker.Power-rusher.Power)*.012f+Running*.06f-Difficulty*.05f-(Difficulty==3?.28f:0),.48f,2.1f);if(Difficulty>=3)blocker.BlockLimit=Math.Min(blocker.BlockLimit,SuperExtreme?.18f:blocker.Role=="OL"?.7f:.28f);}
   // Solid bodies still impede a free rusher after a shed. No scripted position shove.
   if(distance<1.02f){float ox=rusher.OldX-blocker.OldX,oz=rusher.OldZ-blocker.OldZ,old=(float)Math.Sqrt(ox*ox+oz*oz);if(old>.01f&&dx*ox+dz*oz<0){dx=ox/old;dz=oz/old;}else if(distance>.001f){dx/=distance;dz/=distance;}else{dx=0;dz=1;}float push=Math.Min(1.02f-distance,Math.Max(.02f,dt*5));rusher.X+=dx*push*.75f;rusher.Z+=dz*push*.75f;blocker.X-=dx*push*.25f;blocker.Z-=dz*push*.25f;}
  }
 }
}
}
